const input=$json??{}; const event=input.event??input;
const dealId=event.deal_id??event.dealId, leadId=event.lead_id??event.leadId, propertyId=event.property_id??event.propertyId;
const dnc=Boolean(event.dnc??event.do_not_contact), blockers=Array.isArray(event.blockers)?event.blockers:[];
const eligible=event.reengagement_eligible===true||String(event.decision??'').toLowerCase()==='reengagement_eligible';
const phone=event.phone??event.seller?.phone, email=event.email??event.seller?.email;
const preferred=String(event.preferred_channel??event.channel??'').toLowerCase();
const attempts=Number(event.attempts??0), maxAttempts=Number(event.max_attempts??3);
const baseKey=event.idempotency_key??[dealId,leadId,propertyId,'seller-followup'].filter(Boolean).join(':');
const generationKey=baseKey+':message-generation:'+attempts;
let route='WF-357',decision='not_eligible',channel=null;
if(dnc){route='WF-126';decision='dnc_hard_stop';}
else if(blockers.length){route='WF-126';decision='blocked';}
else if(!dealId||!leadId||!propertyId||!baseKey){route='WF-357';decision='identity_or_idempotency_missing';}
else if(!eligible){route='WF-357';decision='reengagement_not_eligible';}
else if(attempts>=maxAttempts){route='WF-126';decision='human_review_max_attempts';}
else {
  channel=preferred==='email'&&email?'email':preferred==='sms'&&phone?'sms':phone?'sms':email?'email':null;
  if(!channel){route='WF-352';decision='seller_contact_missing';}
  else {route='WF-346';decision='message_generation_ready';}
}
return [{json:{...event,workflow:'WF-358',decision,route,channel,deal_id:dealId,lead_id:leadId,property_id:propertyId,phone,email,attempts,max_attempts:maxAttempts,generation_idempotency_key:generationKey,message_generation_brief:{objective:'re-engage seller without over-contacting',channel,attempt:attempts+1,include_property_context:Boolean(event.property_context),include_offer_context:Boolean(event.offer_context)},audit_event:'reengagement_message_generation_channel_selection'}}];
